import { readFile, writeFile } from "node:fs/promises";

const base = new URL("../", import.meta.url);
const schema = JSON.parse(await readFile(new URL("tools/oengine-asset-core/geometry-layout-v4.json", base)));
const ts =
  "// Generated by tools/generate-geometry-layout.mjs; edit geometry-layout-v4.json.\n" +
  `export const GEOMETRY_LAYOUT_V4 = ${JSON.stringify(schema, null, 2)} as const;\n`;
const entries = [
  ["meshletHeaderBytes", schema.meshletHeaderBytes],
  ...Object.entries(schema.meshlet).map(([key, value]) => [`meshlet_${key}`, value]),
  ...Object.entries(schema.vertex).map(([key, value]) => [`vertex_${key}`, value])
];
const header =
  "// Generated by tools/generate-geometry-layout.mjs; edit geometry-layout-v4.json.\n#pragma once\n" +
  "namespace oengine::asset::layout_v4 {\n" +
  entries.map(([key, value]) => `inline constexpr unsigned ${key} = ${value}u;`).join("\n") +
  "\n}\n";
for (const [path, content] of [
  ["src/assets/GeometryLayoutV4.generated.ts", ts],
  ["tools/oengine-asset-core/include/oengine_asset/GeometryLayoutV4.generated.h", header]
]) {
  const url = new URL(path, base);
  if (process.argv.includes("--check")) {
    if ((await readFile(url, "utf8")) !== content) throw new Error(`Stale ABI layout: ${path}`);
  } else {
    await writeFile(url, content);
  }
}
